// Génère le message personnalisé selon le secteur et le pays
const p = $json;
const nom = p.Nom || 'votre établissement';
const secteur = (p.Secteur || '').toLowerCase();
const pays = p.Pays || 'France';

// Templates par secteur
let intro = '';
let offre = '';
let prix = '';

if (secteur.includes('restaurant') || secteur.includes('ristorante') || secteur.includes('restaurante')) {
  intro = `Bonjour,\n\nJ'ai trouvé *${nom}* sur Google Maps et j'ai remarqué que vous n'avez pas encore de site web.`;
  offre = `Aujourd'hui, 87% des clients cherchent un restaurant en ligne avant de se déplacer. Sans site web, vous perdez des réservations chaque jour.`;
  prix = pays === 'Cameroun' ? '150 000 FCFA' : '150€';
} else if (secteur.includes('coiffure') || secteur.includes('parrucchiere') || secteur.includes('peluqueria') || secteur.includes('salon')) {
  intro = `Bonjour,\n\nJ'ai trouvé *${nom}* sur Google Maps et j'ai remarqué que vous n'avez pas encore de site web.`;
  offre = `Un site web vous permet d'accepter des réservations en ligne 24h/24, même quand vous êtes occupé(e). Vos clients peuvent réserver directement sans vous appeler.`;
  prix = pays === 'Cameroun' ? '100 000 FCFA' : '120€';
} else {
  intro = `Bonjour,\n\nJ'ai trouvé *${nom}* sur Google Maps et j'ai remarqué que vous n'avez pas encore de présence web.`;
  offre = `En 2026, ne pas avoir de site web, c'est comme ne pas exister pour des milliers de clients potentiels dans votre zone.`;
  prix = pays === 'Cameroun' ? '120 000 FCFA' : '140€';
}

const message = `${intro}\n\n${offre}\n\n✅ *Chez KEN Digital, on crée votre site en 7 jours à partir de ${prix}*, avec :\n• Design professionnel sur mesure\n• Réservation / contact en ligne\n• Visibilité Google (SEO)\n• Adapté mobile\n\nRépondez simplement *OUI* à ce message et je vous envoie une proposition gratuite sous 24h. 🙏\n\n— *Ken*\nKEN Digital Innovations\n📞 +237 654 270 447`;

return [{
  json: {
    ...p,
    message_wa: message,
    prix: prix
  }
}];
